SET NAMES utf8mb4; SET FOREIGN_KEY_CHECKS=0;
CREATE TABLE clubs (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,address VARCHAR(255),phone VARCHAR(40),logo_path VARCHAR(255),tv_token CHAR(32) NOT NULL UNIQUE,loyalty_points_rate DECIMAL(10,2) NOT NULL DEFAULT 10,loyalty_redemption_rate DECIMAL(10,2) NOT NULL DEFAULT 1,currency_symbol VARCHAR(10) NOT NULL DEFAULT 'Rs.',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,club_id INT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL,password VARCHAR(255) NOT NULL,role ENUM('owner','manager','cashier','operator') NOT NULL DEFAULT 'operator',is_active TINYINT(1) NOT NULL DEFAULT 1,last_login DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_user_email (email),KEY idx_users_club (club_id),CONSTRAINT fk_users_club FOREIGN KEY(club_id) REFERENCES clubs(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE rate_plans (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,club_id INT UNSIGNED NOT NULL,plan_name VARCHAR(100) NOT NULL,billing_type ENUM('per_minute','slab','per_frame','challenge') NOT NULL,rate_per_minute DECIMAL(10,2) NOT NULL DEFAULT 0,rate_per_frame DECIMAL(10,2) NOT NULL DEFAULT 0,slab_config JSON NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_rate_club (club_id),CONSTRAINT fk_rate_club FOREIGN KEY(club_id) REFERENCES clubs(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE tables (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,club_id INT UNSIGNED NOT NULL,table_number VARCHAR(20) NOT NULL,table_name VARCHAR(100),table_type ENUM('snooker','pool','billiards') NOT NULL DEFAULT 'snooker',status ENUM('available','running','paused','held','closed') NOT NULL DEFAULT 'available',rate_plan_id INT UNSIGNED NULL,is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_table_number (club_id,table_number),KEY idx_table_club_status(club_id,status),CONSTRAINT fk_table_club FOREIGN KEY(club_id) REFERENCES clubs(id) ON DELETE CASCADE,CONSTRAINT fk_table_rate FOREIGN KEY(rate_plan_id) REFERENCES rate_plans(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE players (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,club_id INT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,phone VARCHAR(40),email VARCHAR(190),photo_path VARCHAR(255),date_of_birth DATE NULL,tier ENUM('regular','silver','gold','platinum') NOT NULL DEFAULT 'regular',loyalty_points INT NOT NULL DEFAULT 0,total_spent DECIMAL(12,2) NOT NULL DEFAULT 0,total_visits INT NOT NULL DEFAULT 0,ledger_balance DECIMAL(12,2) NOT NULL DEFAULT 0,member_rate_override DECIMAL(5,2) NOT NULL DEFAULT 0,joined_date DATE NULL,last_visit DATETIME NULL,is_active TINYINT(1) NOT NULL DEFAULT 1,notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_player_club_name(club_id,name),KEY idx_player_phone(club_id,phone),CONSTRAINT fk_player_club FOREIGN KEY(club_id) REFERENCES clubs(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE player_loyalty_log (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,player_id INT UNSIGNED NOT NULL,session_id INT UNSIGNED NULL,points_change INT NOT NULL,reason VARCHAR(255) NOT NULL,balance_after INT NOT NULL,created_by INT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,KEY idx_loyalty_player(player_id,created_at),CONSTRAINT fk_loyalty_player FOREIGN KEY(player_id) REFERENCES players(id) ON DELETE CASCADE,CONSTRAINT fk_loyalty_session FOREIGN KEY(session_id) REFERENCES sessions(id) ON DELETE SET NULL,CONSTRAINT fk_loyalty_user FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE shifts (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,club_id INT UNSIGNED NOT NULL,operator_id INT UNSIGNED NOT NULL,start_time DATETIME NOT NULL,end_time DATETIME NULL,opening_cash DECIMAL(12,2) NOT NULL DEFAULT 0,closing_cash DECIMAL(12,2) NULL,expected_cash DECIMAL(12,2) NULL,cash_discrepancy DECIMAL(12,2) NULL,total_revenue DECIMAL(12,2) NOT NULL DEFAULT 0,total_transactions INT NOT NULL DEFAULT 0,status ENUM('open','closed') NOT NULL DEFAULT 'open',notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,KEY idx_shift_club_status(club_id,status),CONSTRAINT fk_shift_club FOREIGN KEY(club_id) REFERENCES clubs(id) ON DELETE CASCADE,CONSTRAINT fk_shift_user FOREIGN KEY(operator_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE sessions (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,club_id INT UNSIGNED NOT NULL,table_id INT UNSIGNED NOT NULL,player_id INT UNSIGNED NULL,player_name_walkin VARCHAR(120),operator_id INT UNSIGNED NOT NULL,shift_id INT UNSIGNED NULL,start_time DATETIME NOT NULL,end_time DATETIME NULL,pause_start DATETIME NULL,total_pause_seconds INT NOT NULL DEFAULT 0,billing_type ENUM('per_minute','slab','per_frame','challenge') NOT NULL,rate_plan_id INT UNSIGNED NULL,frames_played INT NOT NULL DEFAULT 0,challenge_amount DECIMAL(12,2) NOT NULL DEFAULT 0,table_amount DECIMAL(12,2) NOT NULL DEFAULT 0,cafe_amount DECIMAL(12,2) NOT NULL DEFAULT 0,total_amount DECIMAL(12,2) NOT NULL DEFAULT 0,discount_amount DECIMAL(12,2) NOT NULL DEFAULT 0,points_used INT NOT NULL DEFAULT 0,points_earned INT NOT NULL DEFAULT 0,payment_method ENUM('cash','jazzcash','easypaisa','ledger','mixed') NULL,status ENUM('running','paused','held','completed','cancelled') NOT NULL DEFAULT 'running',notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_session_club_status(club_id,status),KEY idx_session_table_status(table_id,status),KEY idx_session_dates(club_id,end_time),CONSTRAINT fk_session_club FOREIGN KEY(club_id) REFERENCES clubs(id) ON DELETE CASCADE,CONSTRAINT fk_session_table FOREIGN KEY(table_id) REFERENCES tables(id),CONSTRAINT fk_session_player FOREIGN KEY(player_id) REFERENCES players(id) ON DELETE SET NULL,CONSTRAINT fk_session_operator FOREIGN KEY(operator_id) REFERENCES users(id),CONSTRAINT fk_session_shift FOREIGN KEY(shift_id) REFERENCES shifts(id) ON DELETE SET NULL,CONSTRAINT fk_session_rate FOREIGN KEY(rate_plan_id) REFERENCES rate_plans(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE session_frames (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,session_id INT UNSIGNED NOT NULL,frame_number INT NOT NULL,winner_player VARCHAR(120),duration_seconds INT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,KEY idx_frame_session(session_id),CONSTRAINT fk_frame_session FOREIGN KEY(session_id) REFERENCES sessions(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE held_bills (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,club_id INT UNSIGNED NOT NULL,session_id INT UNSIGNED NOT NULL,player_id INT UNSIGNED NULL,amount DECIMAL(12,2) NOT NULL,notes TEXT,held_at DATETIME NOT NULL,settled_at DATETIME NULL,settled_by INT UNSIGNED NULL,status ENUM('held','settled','cancelled') NOT NULL DEFAULT 'held',KEY idx_held_club_status(club_id,status),CONSTRAINT fk_held_club FOREIGN KEY(club_id) REFERENCES clubs(id) ON DELETE CASCADE,CONSTRAINT fk_held_session FOREIGN KEY(session_id) REFERENCES sessions(id) ON DELETE CASCADE,CONSTRAINT fk_held_player FOREIGN KEY(player_id) REFERENCES players(id) ON DELETE SET NULL,CONSTRAINT fk_held_user FOREIGN KEY(settled_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE cafe_items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,club_id INT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,category VARCHAR(80) NOT NULL DEFAULT 'Other',price DECIMAL(10,2) NOT NULL,stock_quantity INT NOT NULL DEFAULT 0,low_stock_threshold INT NOT NULL DEFAULT 0,is_available TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_cafe_club_available(club_id,is_available),CONSTRAINT fk_cafe_club FOREIGN KEY(club_id) REFERENCES clubs(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE cafe_orders (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,session_id INT UNSIGNED NULL,club_id INT UNSIGNED NOT NULL,player_id INT UNSIGNED NULL,operator_id INT UNSIGNED NOT NULL,is_standalone TINYINT(1) NOT NULL DEFAULT 0,total_amount DECIMAL(12,2) NOT NULL DEFAULT 0,payment_method VARCHAR(30) NULL,status ENUM('open','completed','cancelled') NOT NULL DEFAULT 'open',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,KEY idx_cafe_order_session(session_id),KEY idx_cafe_order_club(club_id),CONSTRAINT fk_order_session FOREIGN KEY(session_id) REFERENCES sessions(id) ON DELETE SET NULL,CONSTRAINT fk_order_club FOREIGN KEY(club_id) REFERENCES clubs(id) ON DELETE CASCADE,CONSTRAINT fk_order_player FOREIGN KEY(player_id) REFERENCES players(id) ON DELETE SET NULL,CONSTRAINT fk_order_user FOREIGN KEY(operator_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE cafe_order_items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id INT UNSIGNED NOT NULL,cafe_item_id INT UNSIGNED NULL,item_name VARCHAR(120) NOT NULL,item_price DECIMAL(10,2) NOT NULL,quantity INT NOT NULL,subtotal DECIMAL(12,2) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,KEY idx_order_item_order(order_id),CONSTRAINT fk_order_item_order FOREIGN KEY(order_id) REFERENCES cafe_orders(id) ON DELETE CASCADE,CONSTRAINT fk_order_item_cafe FOREIGN KEY(cafe_item_id) REFERENCES cafe_items(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE expenses (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,club_id INT UNSIGNED NOT NULL,category ENUM('electricity','rent','water','salaries','equipment','maintenance','miscellaneous') NOT NULL,amount DECIMAL(12,2) NOT NULL,description TEXT,expense_date DATE NOT NULL,receipt_note VARCHAR(255),added_by INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_expense_club_date(club_id,expense_date),CONSTRAINT fk_expense_club FOREIGN KEY(club_id) REFERENCES clubs(id) ON DELETE CASCADE,CONSTRAINT fk_expense_user FOREIGN KEY(added_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE inventory_items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,club_id INT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,category ENUM('cafe_stock','equipment') NOT NULL,current_stock DECIMAL(12,2) NOT NULL DEFAULT 0,unit VARCHAR(30) NOT NULL DEFAULT 'units',low_stock_threshold DECIMAL(12,2) NOT NULL DEFAULT 0,cost_per_unit DECIMAL(12,2) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_inventory_club(club_id),CONSTRAINT fk_inventory_club FOREIGN KEY(club_id) REFERENCES clubs(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE inventory_log (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,inventory_item_id INT UNSIGNED NOT NULL,change_quantity DECIMAL(12,2) NOT NULL,change_type ENUM('purchase','sale','adjustment','damage') NOT NULL,vendor_name VARCHAR(120),cost DECIMAL(12,2),notes TEXT,created_by INT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,KEY idx_inventory_log_item(inventory_item_id),CONSTRAINT fk_inventory_log_item FOREIGN KEY(inventory_item_id) REFERENCES inventory_items(id) ON DELETE CASCADE,CONSTRAINT fk_inventory_log_user FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE tournaments (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,club_id INT UNSIGNED NOT NULL,name VARCHAR(150) NOT NULL,sport ENUM('snooker','8ball','9ball') NOT NULL,format ENUM('single_elim','double_elim','round_robin') NOT NULL,match_format ENUM('best_of','race_to') NOT NULL,frames_count INT NOT NULL,entry_fee DECIMAL(12,2) NOT NULL DEFAULT 0,prize_pool DECIMAL(12,2) NOT NULL DEFAULT 0,prize_breakdown JSON NULL,status ENUM('draft','registration','active','completed') NOT NULL DEFAULT 'draft',template_name VARCHAR(120),created_by INT UNSIGNED NOT NULL,started_at DATETIME NULL,completed_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,KEY idx_tournament_club(club_id,status),CONSTRAINT fk_tournament_club FOREIGN KEY(club_id) REFERENCES clubs(id) ON DELETE CASCADE,CONSTRAINT fk_tournament_user FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE tournament_players (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tournament_id INT UNSIGNED NOT NULL,player_id INT UNSIGNED NULL,player_name VARCHAR(120) NOT NULL,seed_number INT NULL,entry_fee_paid TINYINT(1) NOT NULL DEFAULT 0,status ENUM('registered','active','eliminated') NOT NULL DEFAULT 'registered',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,KEY idx_tournament_player(tournament_id),CONSTRAINT fk_tournament_player_t FOREIGN KEY(tournament_id) REFERENCES tournaments(id) ON DELETE CASCADE,CONSTRAINT fk_tournament_player_p FOREIGN KEY(player_id) REFERENCES players(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE tournament_matches (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tournament_id INT UNSIGNED NOT NULL,round_number INT NOT NULL,match_number INT NOT NULL,player1_id INT UNSIGNED NULL,player2_id INT UNSIGNED NULL,player1_name VARCHAR(120),player2_name VARCHAR(120),player1_frames INT NOT NULL DEFAULT 0,player2_frames INT NOT NULL DEFAULT 0,winner_id INT UNSIGNED NULL,winner_name VARCHAR(120),session_id INT UNSIGNED NULL,table_id INT UNSIGNED NULL,status ENUM('pending','running','completed') NOT NULL DEFAULT 'pending',played_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,KEY idx_match_tournament(tournament_id,round_number),CONSTRAINT fk_match_tournament FOREIGN KEY(tournament_id) REFERENCES tournaments(id) ON DELETE CASCADE,CONSTRAINT fk_match_p1 FOREIGN KEY(player1_id) REFERENCES tournament_players(id) ON DELETE SET NULL,CONSTRAINT fk_match_p2 FOREIGN KEY(player2_id) REFERENCES tournament_players(id) ON DELETE SET NULL,CONSTRAINT fk_match_winner FOREIGN KEY(winner_id) REFERENCES tournament_players(id) ON DELETE SET NULL,CONSTRAINT fk_match_session FOREIGN KEY(session_id) REFERENCES sessions(id) ON DELETE SET NULL,CONSTRAINT fk_match_table FOREIGN KEY(table_id) REFERENCES tables(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE leaderboard_entries (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,club_id INT UNSIGNED NOT NULL,player_id INT UNSIGNED NOT NULL,rank_position INT NOT NULL,category VARCHAR(50) NOT NULL,period ENUM('daily','weekly','monthly','alltime') NOT NULL,value DECIMAL(12,2) NOT NULL DEFAULT 0,is_manual TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_leaderboard(club_id,player_id,category,period),CONSTRAINT fk_leader_club FOREIGN KEY(club_id) REFERENCES clubs(id) ON DELETE CASCADE,CONSTRAINT fk_leader_player FOREIGN KEY(player_id) REFERENCES players(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE settings (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,club_id INT UNSIGNED NOT NULL,setting_key VARCHAR(100) NOT NULL,setting_value TEXT,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_setting(club_id,setting_key),CONSTRAINT fk_setting_club FOREIGN KEY(club_id) REFERENCES clubs(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE audit_log (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,club_id INT UNSIGNED NULL,user_id INT UNSIGNED NULL,action VARCHAR(100) NOT NULL,entity_type VARCHAR(100) NOT NULL,entity_id INT UNSIGNED NULL,old_value JSON NULL,new_value JSON NULL,ip_address VARCHAR(45),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,KEY idx_audit_club_created(club_id,created_at),CONSTRAINT fk_audit_club FOREIGN KEY(club_id) REFERENCES clubs(id) ON DELETE SET NULL,CONSTRAINT fk_audit_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE notifications (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,club_id INT UNSIGNED NOT NULL,type VARCHAR(50) NOT NULL,message VARCHAR(255) NOT NULL,is_read TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,KEY idx_notice_club_read(club_id,is_read),CONSTRAINT fk_notice_club FOREIGN KEY(club_id) REFERENCES clubs(id) ON DELETE CASCADE) ENGINE=InnoDB;
SET FOREIGN_KEY_CHECKS=1;
